def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    last_me = me[-1]
    last_opp = opp[-1]

    # Running counts
    opp_c = 0
    opp_d = 0
    my_d = 0
    for i in range(n):
        if opp[i] == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me[i] == 'D':
            my_d += 1

    # Recent window (last 8)
    w = 8
    if n < w:
        w = n
    start = n - w
    r_opp_c = 0
    r_opp_d = 0
    r_my_d = 0
    for i in range(start, n):
        if opp[i] == 'C':
            r_opp_c += 1
        else:
            r_opp_d += 1
        if me[i] == 'D':
            r_my_d += 1

    # Consecutive defections by opponent at the tail
    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec_opp_d += 1
        else:
            break

    # Consecutive cooperations by opponent at the tail
    consec_opp_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            consec_opp_c += 1
        else:
            break

    # Consecutive mutual defection at the tail
    consec_dd = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D' and me[i] == 'D':
            consec_dd += 1
        else:
            break

    # Overall rates
    opp_c_rate = opp_c / n

    # --- Early game: establish cooperation, retaliate once on betrayal ---
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    if n == 2:
        if opp[0] == 'C' and opp[1] == 'C':
            return 'C'
        if opp[1] == 'C':
            return 'C'
        if opp[1] == 'D':
            # one defection so far: give one more chance
            return 'C' if rng.random() < 0.6 else 'D'

    # --- Hostile opponent: pure defector / near-pure ---
    if n >= 5 and opp_c_rate <= 0.15:
        # Rare cooperative probe to escape mutual defection
        if consec_dd >= 4 and rng.random() < 0.18:
            return 'C'
        return 'D'

    # --- Very cooperative opponent: keep cooperating, occasional probe ---
    if opp_c_rate >= 0.9 and opp_d <= 2:
        # Probe very rarely to test responsiveness, but mostly stay C
        if n < 92 and n % 29 == 0:
            return 'D' if rng.random() < 0.12 else 'C'
        return 'C'

    # --- Mostly cooperative but with recent defections ---
    if opp_c_rate >= 0.6:
        if last_opp == 'D':
            # Opponent just defected; retaliate once but quickly forgive
            if consec_opp_d >= 3:
                # Sustained betrayal: punish firmly
                if rng.random() < 0.12:
                    return 'C'
                return 'D'
            if consec_opp_d == 2:
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            # Single defection: retaliate but with good forgiveness chance
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        else:
            # Opponent cooperated last
            return 'C'

    # --- Mixed opponent (0.15 < co-op rate < 0.6) ---
    # Use a tit-for-tat base with limited forgiveness and anti-lock-in escape
    if last_opp == 'D':
        if consec_opp_d >= 3:
            # Heavy retaliation against repeat exploitation
            if consec_dd >= 3 and rng.random() < 0.22:
                return 'C'
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if consec_opp_d == 2:
            if rng.random() < 0.18:
                return 'C'
            return 'D'
        # Single defection: mostly retaliate, sometimes forgive
        if rng.random() < 0.22:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated last;
        # if we have been defecting a lot recently, return to cooperation
        if r_my_d * 2 >= w:
            return 'C'
        # If opponent is fairly cooperative recently, keep cooperating
        if r_opp_c * 2 >= w:
            return 'C'
        # Otherwise, cautiously cooperate but occasionally exploit
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # The above covers all cases, but include safe fallback
    # (unreachable in practice)
    return 'C'
